/* Minimal System V <sys/ioctl.h> for porting Unix sources to OS-9/68k.   The disk's own copy lives at DEFS/UNIX/ioctl.h -- FIONREAD and the tty   flush codes -- and this only puts it where a Unix source looks for it.   Deliberately NOT a place to add tape ioctls: sources that want those   (GNU tar's buffer.c, diffarch.c, rtape_lib.c) guard every use on MTIOCTOP   being defined, so leaving it undefined compiles the right code out. */#include <UNIX/ioctl.h>